namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Room { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = new();
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on civilization." }
        };

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds 3 patents in neural network architectures.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Wright", Title = "Associate Professor of Computer Science", Bio = "Dr. Wright focuses on distributed systems and cloud computing. Previously a senior engineer at a major tech company for 10 years.", Email = "j.wright@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Lopez", Title = "Professor of Mathematics", Bio = "Dr. Lopez is an expert in abstract algebra and number theory. She received the Distinguished Teaching Award in 2023.", Email = "m.lopez@university.edu" },
            new() { Id = 4, Name = "Dr. Robert Kim", Title = "Associate Professor of English", Bio = "Dr. Kim specializes in contemporary American literature and creative writing. Author of three novels and two essay collections.", Email = "r.kim@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Zhao", Title = "Professor of Physics", Bio = "Dr. Zhao researches quantum mechanics and particle physics. She leads the university's particle accelerator lab.", Email = "e.zhao@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Torres", Title = "Associate Professor of History", Bio = "Dr. Torres specializes in medieval European history and the history of science. He has authored two acclaimed books on the Renaissance.", Email = "m.torres@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "TTh 10:30–11:50 AM", Room = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 80, CurrentEnrollment = 72 },
            new() { Id = 3, CourseCode = "CS 310", Title = "Operating Systems", Description = "Principles of operating system design including process management, memory management, file systems, and concurrency.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", Room = "Science Hall 110", DepartmentId = 1, Department = _departments[0], Instructor = instructors[1], IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 45 },
            new() { Id = 4, CourseCode = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and practical applications.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", Room = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 50 },
            new() { Id = 5, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", Room = "Math Building 100", DepartmentId = 2, Department = _departments[1], Instructor = instructors[2], IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 6, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", Room = "Math Building 205", DepartmentId = 2, Department = _departments[1], Instructor = instructors[2], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 7, CourseCode = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their homomorphisms. Includes Sylow theorems, polynomial rings, and field extensions.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", Room = "Math Building 310", DepartmentId = 2, Department = _departments[1], Instructor = instructors[2], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 28 },
            new() { Id = 8, CourseCode = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and rhetorical analysis. Emphasis on argument and evidence.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", Room = "Humanities 105", DepartmentId = 3, Department = _departments[2], Instructor = instructors[3], IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 9, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Includes works by Hawthorne, Twain, Fitzgerald, Morrison, and others.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", Room = "Humanities 210", DepartmentId = 3, Department = _departments[2], Instructor = instructors[3], IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },
            new() { Id = 10, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introductory physics with laboratory component.", Credits = 4, Schedule = "MWF 2:00–2:50 PM + Lab Thu 3:00–5:00 PM", Room = "Physics Lab 101", DepartmentId = 4, Department = _departments[3], Instructor = instructors[4], IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 11, CourseCode = "PHYS 301", Title = "Quantum Mechanics", Description = "Wave functions, Schrödinger equation, quantum states, angular momentum, and perturbation theory.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", Room = "Physics Lab 301", DepartmentId = 4, Department = _departments[3], Instructor = instructors[4], IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 22 },
            new() { Id = 12, CourseCode = "HIST 101", Title = "World Civilizations I", Description = "Survey of world history from prehistory through the Renaissance. Examines major civilizations, cultural exchanges, and transformative events.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Room = "Liberal Arts 400", DepartmentId = 5, Department = _departments[4], Instructor = instructors[5], IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 78 },
            new() { Id = 13, CourseCode = "HIST 320", Title = "The Renaissance", Description = "In-depth study of the European Renaissance: art, science, politics, and philosophy from the 14th to 17th century.", Credits = 3, Schedule = "TTh 3:30–4:50 PM", Room = "Liberal Arts 310", DepartmentId = 5, Department = _departments[4], Instructor = instructors[5], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null, int? minCredits = null, int? maxCredits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (minCredits.HasValue)
            query = query.Where(c => c.Credits >= minCredits.Value);

        if (maxCredits.HasValue)
            query = query.Where(c => c.Credits <= maxCredits.Value);

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        if (course == null) return false;
        if (course.CurrentEnrollment >= course.MaxEnrollment) return false;
        // In production, persist to database
        return true;
    }
}

