@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="row g-3 mb-4">
    <div class="col-md-4">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search" placeholder="Course name, code, or instructor..." />
    </div>
    <div class="col-md-3">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <label for="minCredits" class="form-label">Min Credits</label>
        <input type="number" class="form-control" id="minCredits" name="minCredits" value="@MinCredits" min="1" max="6" />
    </div>
    <div class="col-md-2">
        <label for="maxCredits" class="form-label">Max Credits</label>
        <input type="number" class="form-control" id="maxCredits" name="maxCredits" value="@MaxCredits" min="1" max="6" />
    </div>
    <div class="col-md-1 d-flex align-items-end">
        <button type="submit" class="btn btn-primary">Filter</button>
    </div>
</form>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted">Showing @_courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _courses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor.Name</td>
                        <td>@course.Schedule</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
    [SupplyParameterFromQuery] public int? MinCredits { get; set; }
    [SupplyParameterFromQuery] public int? MaxCredits { get; set; }

    private List<Course> _courses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Search, DepartmentId, MinCredits, MaxCredits);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted Successfully</h4>
        <p>Your enrollment request has been received. You will be notified once it is processed.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Back to Course Catalog</a>
}
else
{
    @if (_error is not null)
    {
        <div class="alert alert-danger">@_error</div>
    }

    <form method="post" class="mt-3" style="max-width: 600px;">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                   value="@Model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                   value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.CourseCode – @course.Title (@course.Credits cr)
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();

    private List<Course> _courses = new();
    private bool _submitted;
    private string? _error;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (Model.CourseId == 0 && CourseId.HasValue)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (Model.StudentName is not null && Model.CourseId > 0 && Model.StudentId is not null
            && Model.StudentName != "" && Model.StudentId != "")
        {
            // Form was posted
            if (string.IsNullOrWhiteSpace(Model.StudentName) || string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId == 0)
            {
                _error = "Please fill in all fields.";
                return;
            }

            var success = Catalog.SubmitEnrollmentRequest(Model);
            if (success)
            {
                _submitted = true;
            }
            else
            {
                _error = "Unable to process enrollment. The course may be full or does not exist.";
            }
        }
    }
}

